{
  "identity": {
    "name": "Idaho PC Solutions, LLC",
    "location": "280 N 8th St, Boise, ID 83702",
    "claims": [
      {
        "statement": "The company operates under the legal name Idaho PC Solutions, LLC.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/",
        "quote": "© 2026 Idaho PC Solutions, LLC. In-shop · On-site · Remote"
      },
      {
        "statement": "The business is located at 280 N 8th St, Boise, ID 83702 and operates by appointment.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/",
        "quote": "Visit by appointment 280 N 8th St Boise, ID 83702"
      },
      {
        "statement": "The business was founded in 2007 and serves Boise and the Treasure Valley.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/",
        "quote": "From one broken laptop to an entire office network, get practical solutions and personal service from a local business founded in 2007."
      },
      {
        "statement": "[redacted] is the Owner and IT technician.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/about-us.html",
        "quote": "MEET YOUR LOCAL TECH [redacted] Owner & IT technician"
      }
    ]
  },
  "industry": {
    "industry": "Computer Repair and Information Technology (IT) Support Services",
    "activities": [
      "Desktop and laptop computer repair and upgrades",
      "Small business IT support and managed IT services",
      "Networking, Wi-Fi, and cabling troubleshooting",
      "Security and malware removal",
      "Data backup and recovery",
      "Cloud and Microsoft 365 configuration and support",
      "Computer setup and data migration",
      "Gaming PC repair and security camera support"
    ],
    "claims": [
      {
        "statement": "Idaho PC Solutions provides computer repair and business IT support for homes and small businesses.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/about-us.html",
        "quote": "Idaho PC Solutions helps people and small businesses throughout Boise and the Treasure Valley solve everyday computer and IT problems."
      },
      {
        "statement": "Services include desktop and laptop repairs, upgrades, malware removal, backups, networking, cloud services, and small-business IT.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/about-us.html",
        "quote": "Support includes desktop and laptop repairs, upgrades, malware removal, backups, networking, cloud services, and small-business IT."
      },
      {
        "statement": "The company also offers support for gaming PCs and security cameras.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/services.html",
        "quote": "Gaming & custom PCs Freezing, graphics problems, startup failures, and compatible upgrades."
      },
      {
        "statement": "The company is an IT and computer repair provider rather than an HVAC, plumbing, or electrical home-service contractor.",
        "label": "inference",
        "sourceUrl": "https://www.idahopcsolutions.com/services.html",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.idahopcsolutions.com/",
    "claims": [
      {
        "statement": "Regular hours are Monday through Friday from 10 a.m. to 6 p.m., with weekends by appointment.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/",
        "quote": "Regular hours are Monday–Friday, 10 a.m.–6 p.m.; weekends and after-hours visits are by appointment and may carry additional fees."
      },
      {
        "statement": "Published starting rates include $95 for standard diagnostics, $120 per hour for on-site support, $95 per hour for remote support, and $145 for malware removal.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/computer-repair-it-pricing.html",
        "quote": "Diagnostics From $95 Hardware, software, startup, freezing, and performance troubleshooting."
      },
      {
        "statement": "On-site support is billed at $120 per hour and remote support at $95 per hour.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/computer-repair-it-pricing.html",
        "quote": "On-site support $120 / hour Computer, printer, network, and IT help at your home or business."
      },
      {
        "statement": "The company serves multiple communities across the Treasure Valley including Boise, Meridian, Nampa, Caldwell, Eagle, Kuna, Star, Middleton, Garden City, Idaho City, and Emmett.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/",
        "quote": "Boise ↗ Meridian ↗ Nampa ↗ Caldwell ↗ Eagle ↗ Kuna ↗ Star ↗ Middleton ↗ Garden City ↗ Idaho City ↗ Emmett ↗"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The website identifies the entity as an LLC (Idaho PC Solutions, LLC).",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/privacy-policy.html",
        "quote": "This policy explains how Idaho PC Solutions, LLC handles information collected through this website, service requests, customer communications, repair and IT services, and payments."
      }
    ],
    "limitations": "No state business registration numbers, contractor license numbers, or professional certifications are published on the inspected pages of the website."
  },
  "existingSoftware": [
    {
      "product": "Wix (manage.wix.com / vbzlife1.wixforms.com)",
      "purpose": "Website services, hosting support, and embedded customer intake forms",
      "evidence": {
        "statement": "The privacy policy states that information is shared with service providers supporting website hosting and forms, including Wix, and the contact page embeds a form from vbzlife1.wixforms.com.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/privacy-policy.html",
        "quote": "Information may be shared with service providers supporting website hosting and forms (including Wix), communications, payment processing, and authorized repair or IT work"
      }
    },
    {
      "product": "Authorize.net",
      "purpose": "Payment processing",
      "evidence": {
        "statement": "The privacy policy states that payments are processed through Authorize.net.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/privacy-policy.html",
        "quote": "When a payment is processed through Authorize.net, information needed for that transaction is provided to Authorize.net and the financial institutions or processors involved."
      }
    },
    {
      "product": "Service Desk application (idaho-pc-solutions-service-desk.floot.app)",
      "purpose": "Internal staff login / service desk portal",
      "evidence": {
        "statement": "All inspected pages reference the host idaho-pc-solutions-service-desk.floot.app alongside a 'Staff Login' footer link.",
        "label": "inference",
        "sourceUrl": "https://www.idahopcsolutions.com/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "Customers requesting service are asked to call, text, email [redacted], or submit a Wix form describing their device, symptoms, and location, after which the business contacts them to discuss the next step.",
      "label": "fact",
      "sourceUrl": "https://www.idahopcsolutions.com/contact-us.html",
      "quote": "Describe your device, the problem, and your location. We’ll contact you to discuss the next step."
    },
    {
      "statement": "The about page presents a single named technician and owner, [redacted], who helps callers decide whether an in-shop, on-site, or remote appointment is appropriate.",
      "label": "fact",
      "sourceUrl": "https://www.idahopcsolutions.com/about-us.html",
      "quote": "[redacted] can help you decide whether the next step is an in-shop appointment, an on-site visit, or remote assistance."
    }
  ],
  "problems": [
    {
      "problem": "As an owner-operated IT and computer repair shop handling inquiries by phone, text, email, and web form, incoming requests while the technician is performing hands-on or on-site work may wait for manual follow-up.",
      "label": "hypothesis",
      "basis": "The site indicates appointments and triage are handled by owner/technician [redacted] across in-shop, on-site, and remote engagements, with manual callback/follow-up after form or phone inquiries."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Wix Forms and Wix Business automations (manage.wix.com / vbzlife1.wixforms.com)",
      "addresses": "Automated form confirmation replies and basic inquiry capture",
      "alreadyOwned": true
    },
    {
      "solution": "Existing service desk web application (idaho-pc-solutions-service-desk.floot.app)",
      "addresses": "Internal ticket and staff service desk management",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because Idaho PC Solutions, LLC is outside ForgeX's target segment of 10-to-75-staff HVAC, plumbing, and electrical contractors, and is itself an IT services provider."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended."
  },
  "humanReview": [
    "No ForgeX automation is recommended; in general, diagnostic quotes and device access authorizations in computer repair require direct human technician review."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Targeting an IT services and computer repair micro-business falls outside ForgeX's home-service contractor segment and risks misallocating sales and implementation resources."
    },
    {
      "type": "security",
      "description": "Customer inquiries in computer repair can inadvertently include sensitive account or device details despite the website's warning not to send passwords or payment details."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "The company is not a fit for ForgeX's services; therefore, no commercial value or implementation cost estimate is recommended."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner & IT technician"
    ],
    "people": [
      {
        "name": "[redacted]",
        "role": "Owner & IT technician",
        "sourceUrl": "https://www.idahopcsolutions.com/about-us.html",
        "quote": "MEET YOUR LOCAL TECH [redacted] Owner & IT technician"
      }
    ],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://www.idahopcsolutions.com/contact-us.html"
      }
    ]
  },
  "discovery": {
    "questions": [
      "How many technicians and support staff currently work at Idaho PC Solutions?",
      "How are incoming web form, text, and email service requests routed into your service desk system today?"
    ],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://www.idahopcsolutions.com/",
        "usedFor": "Company identity, location, hours, service areas, service overview, and technical host references."
      },
      {
        "url": "https://www.idahopcsolutions.com/about-us.html",
        "usedFor": "Owner identity ([redacted], Owner & IT technician), company history, and intake process."
      },
      {
        "url": "https://www.idahopcsolutions.com/contact-us.html",
        "usedFor": "Business contact channels, physical address, and Wix form integration."
      },
      {
        "url": "https://www.idahopcsolutions.com/computer-repair-it-pricing.html",
        "usedFor": "Published service pricing for diagnostics, repairs, remote support, and on-site support."
      },
      {
        "url": "https://www.idahopcsolutions.com/services.html",
        "usedFor": "Full list of computer repair and IT support services."
      },
      {
        "url": "https://www.idahopcsolutions.com/blank-page.html",
        "usedFor": "Terms and conditions and legal entity confirmation."
      },
      {
        "url": "https://www.idahopcsolutions.com/privacy-policy.html",
        "usedFor": "Confirmation of Wix and Authorize.net usage and data handling policies."
      }
    ],
    "limitations": [
      "Exact employee headcount is not stated on the website, though the About page only names a single owner/technician ([redacted]).",
      "No state licensing or registration numbers are published on the website.",
      "Paid lead generation usage is not observable from the inspected pages."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "ForgeX's segment is owner-led home-service contractors (HVAC, plumbing, and electrical) with roughly 10 to 75 staff who pay for leads. Idaho PC Solutions, LLC is a local computer repair and small-business IT support provider in Boise, Idaho, featuring a single named owner and IT technician ([redacted]) and technical expertise to manage its own IT and service-desk systems."
  }
}
